schemaIntrospection.query:
{
    rankBracketBasicEnum: __type(name: "RankBracketBasicEnum") {
      name kind
      enumValues(includeDeprecated: true) { name description isDeprecated }
    }
    heroStatsQuery: __type(name: "HeroStatsQuery") {
      name
      fields {
        name
        args { name description type { kind name ofType { kind name ofType { kind name ofType { kind name } } } } }
      }
    }
    matchupRow: __type(name: "HeroStatsHeroDryadType") {
      name
      fields { name description type { kind name ofType { kind name ofType { kind name ofType { kind name } } } } }
    }
  }

